import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.DSc8fo6x.js";const u=JSON.parse('{"title":"What’s new","description":"","frontmatter":{},"headers":[],"relativePath":"en/yenilikler.md","filePath":"en/yenilikler.md"}'),r={name:"en/yenilikler.md"};function l(s,e,o,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="what-s-new" tabindex="-1">What’s new <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What’s new&quot;">​</a></h1><p>Changes by program version (newest first).</p><h2 id="_12-10-2026" tabindex="-1">12.10.2026 <a class="header-anchor" href="#_12-10-2026" aria-label="Permalink to &quot;12.10.2026&quot;">​</a></h2><ul><li>Help: the “Help” menu at the bottom left and “?” on every page — the user guide opens inside the program, offline (3 languages).</li><li>A printable cashier quick guide (PDF), keyboard shortcuts.</li><li>A “Getting started” checklist for the admin: shop details, first product, cashier, printer, Telegram.</li><li>Online guide, videos and PDFs: camalzadeh.github.io/kassa-docs</li><li>Training mode: a new cashier practises selling, sales are not recorded (admin only, time-limited).</li><li>Fixed: unsaved changes in Settings could disappear by themselves on a slow computer.</li></ul><h2 id="_12-10-2026-1" tabindex="-1">12.10.2026 <a class="header-anchor" href="#_12-10-2026-1" aria-label="Permalink to &quot;12.10.2026&quot;">​</a></h2><ul><li>Telegram: after “Find chat” and a successful test message, the token and chat are saved automatically.</li><li>All settings (including defaults) are stored in the database — moving the database restores everything.</li><li>The new Kassa logo is shown everywhere instead of the old black icon.</li></ul><h2 id="_11-10-2026" tabindex="-1">11.10.2026 <a class="header-anchor" href="#_11-10-2026" aria-label="Permalink to &quot;11.10.2026&quot;">​</a></h2><ul><li>Receipt and label printer (e.g. Xprinter): Settings → Printers. Receipts and labels print directly, without a print dialog; test printing.</li><li>The receipt can print automatically after a sale; otherwise use the “Receipt” button in the green notification.</li><li>The cash drawer can open on cash payment (if connected to the printer).</li><li>New label sizes: 50×30, 40×30, 30×20 mm.</li><li>Telegram: sending to a group fixed — when several chats are found, pick one from the list.</li><li>If Telegram has not worked for more than 2 days or the database is damaged, the admin sees a warning on the main screen.</li><li>Scans are no longer cut off (the barcode was split in two); the screen no longer freezes after a restore.</li><li>A new installation needs the installation password.</li></ul><h2 id="_07-10-2026" tabindex="-1">07.10.2026 <a class="header-anchor" href="#_07-10-2026" aria-label="Permalink to &quot;07.10.2026&quot;">​</a></h2><ul><li>Languages: Azerbaijani, Russian, English. Each user can choose their own language in the menu.</li><li>New “Settings” section: shop details (shown on receipts), theme, text size, lock time, backups and more. All settings are stored in the database.</li><li>The database is backed up automatically before an update; an older program version will not open a newer database.</li><li>If the database is deleted or damaged, the program does not create a new one — a recovery screen opens (using the recovery code).</li><li>Backups can be restored from within the program, and the database can be moved to another disk.</li><li>If the database was replaced with an old copy while the program was closed, the admin is warned.</li><li>Updates are signed: the program installs only official versions (from the internet or from a file).</li><li>Telegram: a daily report and an encrypted backup to the owner’s phone.</li></ul>',10)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
